begin;
select * from no_plan();
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000093');
set local role service_role;
select is((select environment from public.begin_ecpay_checkout('00000000-0000-4000-8000-000000000093','LIVE001','9999999','production')), 'production', 'production checkout explicitly scoped');
select throws_ok($$select public.begin_ecpay_checkout('00000000-0000-4000-8000-000000000093','STAGE999','9999999','stage')$$, 'P0001', null, 'cannot replace production subscription from sandbox');
select throws_ok($$select public.apply_ecpay_snapshot('LIVE001','9999999','1','[]','stage')$$,'P0001',null,'stage cannot apply production payment');
select throws_ok($$select public.confirm_ecpay_cancellation('LIVE001','9999999','stage')$$,'P0001',null,'stage cannot cancel production subscription');
select throws_ok($$select public.record_ecpay_failure('LIVE001','9999999','first','0','failure1','stage')$$,'P0001',null,'stage cannot fail production order');
select is(public.claim_ecpay_sync('LIVE001','9999999','stage'),false,'stage cannot claim production reconciliation');
select public.apply_ecpay_snapshot('LIVE001','9999999','1','[{"key":"901","success":true,"amount":60,"occurred_at":"2090-01-01T02:00:00Z","period_end":"2090-02-01T02:00:00Z","rtn_code":"1"}]','production');
select is((select status from public.get_subscription('00000000-0000-4000-8000-000000000093')),'active','production payment opens rights');
select public.confirm_ecpay_cancellation('LIVE001','9999999','production');
select is((select cancel_at_period_end from public.get_subscription('00000000-0000-4000-8000-000000000093')),true,'production cancellation stops renewal');
select is((select current_period_end from public.get_subscription('00000000-0000-4000-8000-000000000093')),'2090-02-01T02:00:00Z'::timestamptz,'production cancellation preserves paid rights');
select is((public.ecpay_deployment_readiness('production','9999999')->>'schema_version')::integer,2,'readiness schema version');
select is((public.ecpay_deployment_readiness('production','9999999')->>'private_tables')::boolean,true,'readiness validates private ledger');
select is((public.ecpay_deployment_readiness('production','8888888')->>'mismatched_merchant_orders')::integer,1,'readiness detects merchant changes');
reset role;
select ok(not has_function_privilege('anon','public.ecpay_deployment_readiness(text,text)','EXECUTE'),'anonymous cannot inspect readiness');
select ok(not has_function_privilege('authenticated','public.ecpay_deployment_readiness(text,text)','EXECUTE'),'browser cannot inspect readiness');
select * from finish();
rollback;
